assert set(changes)<=set(ids) and len(changes)==10
seen=[]
for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 def repl(m):
  if m[1] not in changes:return m[0]
  seen.append(m[1]);return '=== '+m[1]+'\n'+changes[m[1]]+'\n\n'
 out=re.sub(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',repl,s,flags=re.S|re.M)
 if out!=s:p.write_text(out)
assert set(seen)==set(changes)
print('Handwritten revised blocks:',','.join(seen))
